package com.yuegang.zhihui.system.api;
import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.common.security.*;import com.yuegang.zhihui.common.web.*;import com.yuegang.zhihui.system.application.*;import com.yuegang.zhihui.system.security.*;import jakarta.servlet.http.*;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/system/users") public final class AuthorizationController{private final AuthorizationService service;private final SystemTrustedUserContextResolver users;public AuthorizationController(AuthorizationService s,SystemTrustedUserContextResolver u){service=s;users=u;}@GetMapping("/{userId}/authorities")public ApiResponse<AuthoritySnapshot>snapshot(@PathVariable String userId,HttpServletRequest r){CurrentUserPrincipal p=users.resolve(r);if(!p.userId().equals(userId)&&!p.roles().contains("ADMIN"))throw new BusinessException(ErrorCode.PERMISSION_DENIED);return ApiResponse.success(service.snapshot(userId),TraceIdResolver.resolve(r));}@PutMapping("/{userId}/roles")public ApiResponse<AuthoritySnapshot>assign(@PathVariable String userId,@Valid @RequestBody AssignRolesRequest body,HttpServletRequest r){CurrentUserPrincipal p=users.resolve(r);if(!p.roles().contains("ADMIN")&&!p.permissions().contains("system:rbac:write"))throw new BusinessException(ErrorCode.PERMISSION_DENIED);return ApiResponse.success(service.assign(userId,body,Long.parseLong(p.userId())),TraceIdResolver.resolve(r));}}
